let raw = items[0].json.result || items[0].json.text || items[0].json.content || '';

if (typeof raw === 'object') {
    raw = JSON.stringify(raw);
}

// Surgically extract the JSON object, ignoring any conversational filler
const match = raw.match(/\{[\s\S]*\}/);

if (!match) {
  throw new Error("No JSON found in response. Response was: " + raw);
}

const data = JSON.parse(match[0]);

return [{ 
  json: { 
    ...data, 
    iteration: $('Initialize State').item.json.iteration, 
    topic: $('Initialize State').item.json.topic 
  } 
}];
